import json
from pathlib import Path


def generate_latex_macros(artifact_path: Path, out_tex_path: Path) -> None:
    data = json.loads(artifact_path.read_text(encoding="utf-8"))
    meta = data["meta"]
    status = meta["status"]

    lines = [
        "% AUTO-GENERATED BY render_tex_macros.py — ZERO MANUAL NUMBERS",
        f"\\newcommand{{\\ArtifactStatus}}{{{status.upper()}}}",
        f"\\newcommand{{\\ArtifactGitSHA}}{{{meta['git_sha'][:8]}}}",
        f"\\newcommand{{\\EvalSeedCount}}{{{len(meta['evaluation_seeds'])}}}",
    ]

    if status in ("planned", "running") or len(data["summary_table"]) < 2:
        lines.extend([
            "\\newcommand{\\MetricNRMSEBaseline}{\\texttt{[PENDING SWEEP]}}",
            "\\newcommand{\\MetricTNDBaseline}{\\texttt{[PENDING SWEEP]}}",
            "\\newcommand{\\MetricNRMSESmith}{\\texttt{[PENDING SWEEP]}}",
            "\\newcommand{\\MetricTNDSmith}{\\texttt{[PENDING SWEEP]}}",
            "\\newcommand{\\MetricHLDiff}{\\texttt{[PENDING SWEEP]}}",
            "\\newcommand{\\MetricCliffsDelta}{\\texttt{[PENDING SWEEP]}}",
            "\\newcommand{\\MetricHolmP}{\\texttt{[PENDING SWEEP]}}",
        ])
    else:
        row_base = data["summary_table"][0]
        row_smith = data["summary_table"][-1]
        comp = data["ablation_comparisons"][-1]
        lines.extend([
            f"\\newcommand{{\\MetricNRMSEBaseline}}{{{row_base['nrmse_median_pct']:.2f}\\%}}",
            f"\\newcommand{{\\MetricTNDBaseline}}{{{row_base['tnd_median_veh_h']:.1f}}}",
            f"\\newcommand{{\\MetricNRMSESmith}}{{{row_smith['nrmse_median_pct']:.2f}\\%}}",
            f"\\newcommand{{\\MetricTNDSmith}}{{{row_smith['tnd_median_veh_h']:.1f}}}",
            f"\\newcommand{{\\MetricHLDiff}}{{{comp['hl_median_diff']:.2f}}}",
            f"\\newcommand{{\\MetricCliffsDelta}}{{{comp['cliffs_delta']:.2f}}}",
            f"\\newcommand{{\\MetricHolmP}}{{{comp['p_value_holm']:.4f}}}",
        ])

    out_tex_path.parent.mkdir(parents=True, exist_ok=True)
    out_tex_path.write_text("\n".join(lines) + "\n", encoding="utf-8")


if __name__ == "__main__":
    generate_latex_macros(Path("results/ensemble.json"), Path("report/generated_metrics.tex"))
